// Command sort prints the lines of its input in order, as GNU sort does in
// the C locale: by bytes, or by number with -n, reversed with -r.
package main

import (
	"bytes"
	"fmt"
	"io"
	"os"
	"slices"

	"example.com/coreutils/internal/input"
	"example.com/coreutils/internal/opts"
)

func main() {
	os.Exit(run(os.Args[1:], os.Stdin, os.Stdout, os.Stderr))
}

var spec = opts.Spec{
	Flags: "nr",
	Long:  map[string]byte{"numeric-sort": 'n', "reverse": 'r'},
}

// order is how lines compare: by number or by bytes, and whether reversed.
type order struct {
	numeric, reverse bool
}

// compare orders two lines. By bytes, the lines compare as unsigned byte
// strings. By number, the leading numbers compare and lines whose numbers
// are equal fall back to the byte comparison. Reversal reverses the whole
// comparison, the fallback with it.
func (o order) compare(a, b []byte) int {
	c := 0
	if o.numeric {
		c = numcompare(a, b)
	}
	if c == 0 {
		c = bytes.Compare(a, b)
	}
	if o.reverse {
		c = -c
	}
	return c
}

// number is a line's leading number, as -n reads it: its sign, its
// integer digits without leading zeros and its fraction digits without
// trailing zeros.
type number struct {
	neg      bool
	whole    []byte
	fraction []byte
}

// parseNumber reads a line's leading number: blanks, an optional minus,
// digits, and an optional point with more digits. A line that does not
// start with one reads as zero, and so does negative zero.
func parseNumber(s []byte) number {
	i := 0
	for i < len(s) && (s[i] == ' ' || s[i] == '\t') {
		i++
	}
	var n number
	if i < len(s) && s[i] == '-' {
		n.neg = true
		i++
	}
	start := i
	for i < len(s) && s[i] >= '0' && s[i] <= '9' {
		i++
	}
	n.whole = bytes.TrimLeft(s[start:i], "0")
	if i < len(s) && s[i] == '.' {
		i++
		start = i
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			i++
		}
		n.fraction = bytes.TrimRight(s[start:i], "0")
	}
	if len(n.whole) == 0 && len(n.fraction) == 0 {
		n.neg = false
	}
	return n
}

// numcompare compares the leading numbers of two lines exactly, digit by
// digit, however long they are.
func numcompare(a, b []byte) int {
	x, y := parseNumber(a), parseNumber(b)
	if x.neg != y.neg {
		if x.neg {
			return -1
		}
		return 1
	}
	c := magnitude(x, y)
	if x.neg {
		c = -c
	}
	return c
}

func magnitude(x, y number) int {
	if len(x.whole) != len(y.whole) {
		if len(x.whole) < len(y.whole) {
			return -1
		}
		return 1
	}
	if c := bytes.Compare(x.whole, y.whole); c != 0 {
		return c
	}
	return bytes.Compare(x.fraction, y.fraction)
}

func run(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
	given, names, err := opts.Parse(args, spec)
	if err != nil {
		fmt.Fprintf(stderr, "sort: %v\nTry 'sort --help' for more information.\n", err)
		return 2
	}
	var o order
	for _, g := range given {
		switch g.Name {
		case 'n':
			o.numeric = true
		case 'r':
			o.reverse = true
		}
	}
	srcs, err := input.Read(names, stdin)
	if err != nil {
		fmt.Fprintf(stderr, "sort: %v\n", err)
		return 2
	}
	var lines [][]byte
	for _, s := range srcs {
		lines = append(lines, input.Lines(s.Data)...)
	}
	slices.SortStableFunc(lines, o.compare)
	for _, l := range lines {
		stdout.Write(append(l, '\n'))
	}
	return 0
}
package main

import (
	"bytes"
	"strings"
	"testing"
)

// sorted runs the command on lines given on standard input and returns
// the lines it printed, failing the test unless it exits 0.
func sorted(t *testing.T, stdin string, args ...string) string {
	t.Helper()
	var out, errOut bytes.Buffer
	if code := run(args, strings.NewReader(stdin), &out, &errOut); code != 0 {
		t.Fatalf("sort %q: exit %d: %s", args, code, errOut.String())
	}
	return out.String()
}

func TestSortKeepsAnUnterminatedLastLine(t *testing.T) {
	if got := sorted(t, "b\na"); got != "a\nb\n" {
		t.Errorf("sort of \"b\\na\" = %q, want a and b, each with its newline", got)
	}
}

func TestSortRefusesAnUnknownFlag(t *testing.T) {
	var out, errOut bytes.Buffer
	code := run([]string{"-nZ"}, strings.NewReader("2\n1\n"), &out, &errOut)
	if code != 2 || out.Len() != 0 || !strings.Contains(errOut.String(), "'Z'") {
		t.Errorf("sort -nZ: exit %d, stdout %q, stderr %q; want exit 2, no output, Z named", code, out.String(), errOut.String())
	}
}

func TestLinesSortByTheirBytes(t *testing.T) {
	if got := sorted(t, "b\nB\na\nA\nab\n"); got != "A\nB\na\nab\nb\n" {
		t.Errorf("sort = %q, want A B a ab b", got)
	}
}

func TestReverseReversesTheOrder(t *testing.T) {
	if got := sorted(t, "b\nB\na\nA\nab\n", "-r"); got != "b\nab\na\nB\nA\n" {
		t.Errorf("sort -r = %q, want b ab a B A", got)
	}
}

func TestNumbersSortByValue(t *testing.T) {
	if got := sorted(t, "10\n9\n-1\n2.5\n", "-n"); got != "-1\n2.5\n9\n10\n" {
		t.Errorf("sort -n = %q, want -1 2.5 9 10", got)
	}
}

func TestANonNumberReadsAsZero(t *testing.T) {
	// The zeros tie and fall back to bytes: "+5" < "-0" < "abc".
	if got := sorted(t, "1\nabc\n-1\n+5\n-0\n", "-n"); got != "-1\n+5\n-0\nabc\n1\n" {
		t.Errorf("sort -n = %q, want -1, the zeros by bytes, 1", got)
	}
}

func TestEqualNumbersTieByBytes(t *testing.T) {
	if got := sorted(t, "2.50\n2.5\n", "-n"); got != "2.5\n2.50\n" {
		t.Errorf("sort -n = %q, want 2.5 then 2.50", got)
	}
	if got := sorted(t, "2.5\n2.50\n", "-rn"); got != "2.50\n2.5\n" {
		t.Errorf("sort -rn = %q, want 2.50 then 2.5", got)
	}
}

func TestNumbersCompareExactly(t *testing.T) {
	in := "99999999999999999999\n99999999999999999998\n-99999999999999999998\n-99999999999999999999\n"
	want := "-99999999999999999999\n-99999999999999999998\n99999999999999999998\n99999999999999999999\n"
	if got := sorted(t, in, "-n"); got != want {
		t.Errorf("sort -n = %q, want %q", got, want)
	}
}
// Package opts splits a tool's arguments into options and operands, the
// way GNU's getopt does for the options the tools know.
package opts

import (
	"fmt"
	"strings"
)

// Opt is one option as given: its short name and, for an option that
// takes one, its value.
type Opt struct {
	Name  byte
	Value string
}

// Spec is what a tool knows: its short options without a value, those
// with one, and its long options by the short name each stands for.
type Spec struct {
	Flags  string
	Valued string
	Long   map[string]byte
}

// Parse splits args into options, in the order given, and operands.
// Options may come anywhere before "--"; short ones may be clustered, and
// a valued one takes the rest of its cluster or the next argument. "-"
// alone is an operand. An option the tool does not know, or a value
// missing, is an error in GNU's words.
func Parse(args []string, spec Spec) ([]Opt, []string, error) {
	var opts []Opt
	var operands []string
	for i := 0; i < len(args); i++ {
		a := args[i]
		switch {
		case a == "--":
			return opts, append(operands, args[i+1:]...), nil
		case strings.HasPrefix(a, "--"):
			name, value, hasValue := strings.Cut(a[2:], "=")
			short, ok := spec.Long[name]
			if !ok {
				return nil, nil, fmt.Errorf("unrecognized option '%s'", a)
			}
			if strings.IndexByte(spec.Valued, short) >= 0 {
				if !hasValue {
					if i+1 >= len(args) {
						return nil, nil, fmt.Errorf("option '--%s' requires an argument", name)
					}
					i++
					value = args[i]
				}
			} else if hasValue {
				return nil, nil, fmt.Errorf("option '--%s' doesn't allow an argument", name)
			}
			opts = append(opts, Opt{Name: short, Value: value})
		case len(a) > 1 && a[0] == '-':
			for j := 1; j < len(a); j++ {
				c := a[j]
				switch {
				case strings.IndexByte(spec.Valued, c) >= 0:
					value := a[j+1:]
					if value == "" {
						if i+1 >= len(args) {
							return nil, nil, fmt.Errorf("option requires an argument -- '%c'", c)
						}
						i++
						value = args[i]
					}
					opts = append(opts, Opt{Name: c, Value: value})
					j = len(a)
				case strings.IndexByte(spec.Flags, c) >= 0:
					opts = append(opts, Opt{Name: c})
				default:
					return nil, nil, fmt.Errorf("invalid option -- '%c'", c)
				}
			}
		default:
			operands = append(operands, a)
		}
	}
	return opts, operands, nil
}
// Package input reads what the tools read: standard input when no file is
// named, else each named file in turn, split into lines.
package input

import (
	"bytes"
	"io"
	"os"
)

// Source is one input a tool reads: its name as given on the command line,
// empty for standard input, and its bytes.
type Source struct {
	Name string
	Data []byte
	// Regular reports whether the input is a regular file, whose size is
	// known before it is read.
	Regular bool
	Size    int64
}

// Read reads the inputs a tool was given: standard input when names is
// empty, else each named file in order. It stops at the first file it
// cannot read and returns the sources read so far with the error.
func Read(names []string, stdin io.Reader) ([]Source, error) {
	if len(names) == 0 {
		data, err := io.ReadAll(stdin)
		if err != nil {
			return nil, err
		}
		return []Source{{Data: data}}, nil
	}
	var out []Source
	for _, name := range names {
		src, err := ReadFile(name)
		if err != nil {
			return out, err
		}
		out = append(out, src)
	}
	return out, nil
}

// ReadFile reads one named file.
func ReadFile(name string) (Source, error) {
	data, err := os.ReadFile(name)
	if err != nil {
		return Source{}, err
	}
	src := Source{Name: name, Data: data}
	if fi, err := os.Stat(name); err == nil && fi.Mode().IsRegular() {
		src.Regular, src.Size = true, fi.Size()
	}
	return src, nil
}

// Lines splits data into its lines, each without its newline. A final
// line that lacks a newline is still a line; an empty input has none.
func Lines(data []byte) [][]byte {
	if len(data) == 0 {
		return nil
	}
	data = bytes.TrimSuffix(data, []byte{'\n'})
	return bytes.Split(data, []byte{'\n'})
}
# coreutils

Go clones of GNU coreutils' `cut`, `sort`, `uniq` and `wc`, meant as
drop-in replacements for GNU coreutils 9.4 in the C locale (`LC_ALL=C`):
for every flag a tool supports, its output and exit status are GNU's.

Each tool is its own command, `cmd/<tool>`, built with
`go build ./cmd/<tool>`; what they share lives in `internal/`.

| Tool | Supports |
|---|---|
| `wc` | `-l`, `-w`, `-c` (and `--lines`, `--words`, `--bytes`) |
| `cut` | `-f LIST` with `-d DELIM` (and `--fields`, `--delimiter`) |
| `sort` | plain, `-n`, `-r` (and `--numeric-sort`, `--reverse`) |
| `uniq` | plain, `-c` (and `--count`), one input file |

Every tool reads standard input when no file is named, else the named
files. `go test ./...` runs the tests.
