package main

import (
	"fmt"
	"math"
)

// noTab means no -t was given: fields are then separated by the empty
// string before each run of blanks, so a field keeps its leading blanks.
const noTab = -1

// key is one sort key, as -k gives it, with GNU's zero-based positions:
// the key starts at character schar of field sword and ends at character
// echar of field eword, an echar of zero meaning the end of that field
// and an eword of -1 the end of the line.
type key struct {
	sword, schar int
	eword, echar int
	// skipStart and skipEnd skip blanks before the start and end
	// positions, as b does after POS1 and after POS2.
	skipStart, skipEnd bool
	numeric, reverse   bool
}

// plain reports whether the key gives no ordering options of its own, in
// which case it takes the global ones.
func (k key) plain() bool {
	return !k.skipStart && !k.skipEnd && !k.numeric && !k.reverse
}

func isBlank(c byte) bool { return c == ' ' || c == '\t' }

// begin returns where the key starts in line.
func (k key) begin(line []byte, tab int) int {
	p, lim := 0, len(line)
	for n := k.sword; p < lim && n > 0; n-- {
		if tab != noTab {
			for p < lim && int(line[p]) != tab {
				p++
			}
			if p < lim {
				p++
			}
		} else {
			for p < lim && isBlank(line[p]) {
				p++
			}
			for p < lim && !isBlank(line[p]) {
				p++
			}
		}
	}
	if k.skipStart {
		for p < lim && isBlank(line[p]) {
			p++
		}
	}
	return p + min(lim-p, k.schar)
}

// limit returns where the key ends in line.
func (k key) limit(line []byte, tab int) int {
	p, lim := 0, len(line)
	if k.eword < 0 {
		return lim
	}
	eword, echar := k.eword, k.echar
	if echar == 0 {
		eword++ // take all of the end field
	}
	for p < lim && eword > 0 {
		eword--
		if tab != noTab {
			for p < lim && int(line[p]) != tab {
				p++
			}
			if p < lim && (eword > 0 || echar > 0) {
				p++
			}
		} else {
			for p < lim && isBlank(line[p]) {
				p++
			}
			for p < lim && !isBlank(line[p]) {
				p++
			}
		}
	}
	if echar != 0 {
		if k.skipEnd {
			for p < lim && isBlank(line[p]) {
				p++
			}
		}
		p += min(lim-p, echar)
	}
	return p
}

// field returns the part of line the key covers, empty when the key ends
// before it starts.
func (k key) field(line []byte, tab int) []byte {
	b, e := k.begin(line, tab), k.limit(line, tab)
	return line[b:max(b, e)]
}

// parseKey reads a -k argument, POS1[,POS2], each POS being F[.C][OPTS],
// with GNU's error messages.
func parseKey(spec string) (key, error) {
	bad := func(msg string) error {
		return fmt.Errorf("%s: invalid field specification '%s'", msg, spec)
	}
	k := key{eword: -1}
	s := spec
	var err error
	if k.sword, s, err = count(s, "invalid number at field start"); err != nil {
		return k, err
	}
	if k.sword == 0 {
		return k, bad("field number is zero")
	}
	k.sword--
	if len(s) > 0 && s[0] == '.' {
		if k.schar, s, err = count(s[1:], "invalid number after '.'"); err != nil {
			return k, err
		}
		if k.schar == 0 {
			return k, bad("character offset is zero")
		}
		k.schar--
	}
	if s, err = k.options(s, true, spec); err != nil {
		return k, err
	}
	if len(s) > 0 && s[0] == ',' {
		if k.eword, s, err = count(s[1:], "invalid number after ','"); err != nil {
			return k, err
		}
		if k.eword == 0 {
			return k, bad("field number is zero")
		}
		k.eword--
		if len(s) > 0 && s[0] == '.' {
			if k.echar, s, err = count(s[1:], "invalid number after '.'"); err != nil {
				return k, err
			}
		}
		if s, err = k.options(s, false, spec); err != nil {
			return k, err
		}
	}
	if s != "" {
		return k, bad("stray character in field spec")
	}
	return k, nil
}

// count reads the decimal number s starts with, a number too large to
// hold reading as the largest there is, and returns the rest of s.
func count(s, msg string) (int, string, error) {
	i, n := 0, 0
	for i < len(s) && s[i] >= '0' && s[i] <= '9' {
		d := int(s[i] - '0')
		if n > (math.MaxInt/2-d)/10 {
			n = math.MaxInt / 2 // room left for the arithmetic on it
		} else {
			n = n*10 + d
		}
		i++
	}
	if i == 0 {
		return 0, s, fmt.Errorf("%s: invalid count at start of '%s'", msg, s)
	}
	return n, s[i:], nil
}

// options reads the ordering letters after a key position and returns
// what follows them. b applies to the position it follows.
func (k *key) options(s string, start bool, spec string) (string, error) {
	for ; s != ""; s = s[1:] {
		switch c := s[0]; c {
		case 'b':
			if start {
				k.skipStart = true
			} else {
				k.skipEnd = true
			}
		case 'n':
			k.numeric = true
		case 'r':
			k.reverse = true
		case 'd', 'f', 'g', 'h', 'i', 'M', 'R', 'V':
			return s, fmt.Errorf("ordering option '%c' in key '%s' is not supported", c, spec)
		default:
			return s, nil
		}
	}
	return s, nil
}

// parseTab reads a -t argument: one byte, or "\0" for the null byte.
func parseTab(s string) (int, error) {
	switch {
	case s == "":
		return 0, fmt.Errorf("empty tab")
	case len(s) == 1:
		return int(s[0]), nil
	case s == `\0`:
		return 0, nil
	default:
		return 0, fmt.Errorf("multi-character tab '%s'", s)
	}
}

