func parseTab(s string) (int, error) {
	switch {
	case s == "":
		return 0, fmt.Errorf("empty tab")
	case len(s) == 1:
		return int(s[0]), nil
	case s == `\0`:
		return 0, nil
	default:
		return 0, fmt.Errorf("multi-character tab '%s'", s)
	}
}

