func TestKeySortsPasswdByUID(t *testing.T) {
	in := "root:x:0:0\nbob:x:1000:1000\ndaemon:x:1:1\nal:x:999:999\n"
	want := "root:x:0:0\ndaemon:x:1:1\nal:x:999:999\nbob:x:1000:1000\n"
	if got := sorted(t, in, "-t:", "-k3,3n"); got != want {
		t.Errorf("sort -t: -k3,3n = %q, want %q", got, want)
	}
	if got := sorted(t, in, "--field-separator=:", "--key=3,3n"); got != want {
		t.Errorf("sort --field-separator=: --key=3,3n = %q, want %q", got, want)
	}
}

func TestLaterKeysBreakTies(t *testing.T) {
	in := "b:2\na:2\nc:1\n"
	if got := sorted(t, in, "-t:", "-k2,2n", "-k1,1r"); got != "c:1\nb:2\na:2\n" {
		t.Errorf("sort -t: -k2,2n -k1,1r = %q, want c:1 b:2 a:2", got)
	}
}

func TestKeyWithoutEndRunsToTheEndOfTheLine(t *testing.T) {
	// -k2 compares "1:b" with "1:a"; -k2,2 ties and falls back to the line.
	in := "y:1:a\nx:1:b\n"
	if got := sorted(t, in, "-t:", "-k2"); got != "y:1:a\nx:1:b\n" {
		t.Errorf("sort -t: -k2 = %q", got)
	}
	if got := sorted(t, in, "-t:", "-k2,2"); got != "x:1:b\ny:1:a\n" {
		t.Errorf("sort -t: -k2,2 = %q", got)
	}
}

func TestBlankFieldsKeepTheirLeadingBlanks(t *testing.T) {
	// Without -t, field 2 of "a  z" is "  z", which sorts before " y";
	// b skips the blanks.
	in := "b y\na  z\n"
	if got := sorted(t, in, "-k2,2"); got != "a  z\nb y\n" {
		t.Errorf("sort -k2,2 = %q", got)
	}
	if got := sorted(t, in, "-k2b,2"); got != "b y\na  z\n" {
		t.Errorf("sort -k2b,2 = %q", got)
	}
}

func TestCharacterPositions(t *testing.T) {
	if got := sorted(t, "xb2\nya1\n", "-k1.2,1.2"); got != "ya1\nxb2\n" {
		t.Errorf("sort -k1.2,1.2 = %q", got)
	}
}

func TestPlainKeysTakeGlobalOptions(t *testing.T) {
	// -k1,1 takes -n and -r; -k1,1n has its own options and does not.
	in := "2\n10\n1\n"
	if got := sorted(t, in, "-nr", "-k1,1"); got != "10\n2\n1\n" {
		t.Errorf("sort -nr -k1,1 = %q", got)
	}
	if got := sorted(t, in, "-r", "-k1,1n"); got != "1\n2\n10\n" {
		t.Errorf("sort -r -k1,1n = %q", got)
	}
}

func TestBadKeysAndTabs(t *testing.T) {
	for args, want := range map[string]string{
		"-k0":     "sort: field number is zero: invalid field specification '0'\n",
		"-k1.0":   "sort: character offset is zero: invalid field specification '1.0'\n",
		"-k3,":    "sort: invalid number after ',': invalid count at start of ''\n",
		"-k3x":    "sort: stray character in field spec: invalid field specification '3x'\n",
		"-tab":    "sort: multi-character tab 'ab'\n",
		"-t: -t,": "sort: incompatible tabs\n",
	} {
		var out, errOut bytes.Buffer
		code := run(strings.Fields(args), strings.NewReader("a\n"), &out, &errOut)
		if code != 2 || out.Len() != 0 || errOut.String() != want {
			t.Errorf("sort %s: exit %d, stdout %q, stderr %q; want exit 2, %q", args, code, out.String(), errOut.String(), want)
		}
	}
}
